<?php namespace ProcessWire;

/** Moderation and operations workspace for Messenger. */
class ProcessMessenger extends Process {
	public static function getModuleInfo(): array {
		return [
			'title' => 'Messenger',
			'summary' => 'Moderate reports, manage Messenger safety, and deliver administrative broadcasts.',
			'version' => 110,
			'author' => 'Maxim Semenov',
			'icon' => 'comments',
			'requires' => ['Messenger>=1.1.0'],
			'permissionMethod' => 'hasProcessPermission',
			'page' => ['name' => 'messenger', 'parent' => 'setup', 'title' => 'Messenger'],
		];
	}

	public static function hasProcessPermission(array $data): bool {
		$user = $data['user'] ?? null;
		return $user instanceof User && ($user->isSuperuser() || $user->hasPermission(Messenger::PERMISSION_MODERATE) || $user->hasPermission(Messenger::PERMISSION_ADMIN));
	}

	public function init(): void {
		parent::init();
		$config=$this->wire('config');$styleVersion=Messenger::VERSION . '-' . (int)@filemtime($config->paths->Messenger . 'assets/messenger-admin.css');$scriptVersion=Messenger::VERSION . '-' . (int)@filemtime($config->paths->Messenger . 'assets/messenger-admin.js');$config->styles->add($config->urls->Messenger . 'assets/messenger-admin.css?v=' . $styleVersion);$config->scripts->add($config->urls->Messenger . 'assets/messenger-admin.js?v=' . $scriptVersion);
	}

	private function messenger(): Messenger { return $this->wire('modules')->get('Messenger'); }

	public function ___execute(): string {
		$m = $this->messenger();
		if(!$m->canModerate($this->wire('user')) && $m->canAdmin($this->wire('user'))) {
			$this->wire('session')->redirect($this->wire('page')->url . 'broadcasts/');
			return '';
		}
		$stats = $m->moderationStats($this->wire('user'));
		$reports = $m->reports($this->wire('user'), 'open', 20);
		$baseUrl = $this->wire('page')->url;
		$encryption = ['ready' => false, 'plaintext_messages' => 0, 'plaintext_report_fields' => 0];
		try { $encryption = $m->encryptionStatus(); } catch(\Throwable $error) {}
		$plaintext = (int)($encryption['plaintext_messages'] ?? 0) + (int)($encryption['plaintext_report_fields'] ?? 0);
		$encryptionHealthy = (bool)($encryption['ready'] ?? false) && $plaintext === 0;
		$needsAttention = (int)$stats['open_reports'] > 0 || !$encryptionHealthy;
		$this->headline($this->_('Messenger dashboard'));

		$out = $this->nav('dashboard') . '<header class="MessengerAdminHead MessengerDashboardHead"><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Safety operations') . '</p><h2>' . $this->_('Messenger dashboard') . '</h2><p>' . $this->_('Monitor member messaging, resolve safety reports, and verify operational readiness.') . '</p></div><span class="MessengerDashboardState" data-state="' . ($needsAttention ? 'attention' : 'healthy') . '"><i class="fa fa-' . ($needsAttention ? 'exclamation-circle' : 'check-circle') . '" aria-hidden="true"></i>' . ($needsAttention ? $this->_('Needs attention') : $this->_('Operations healthy')) . '</span></header>';

		$metrics = [
			[$this->_('Open reports'), (int)$stats['open_reports'], 'flag', $this->_('Needs moderator review'), $baseUrl . 'reports/?status=open', (int)$stats['open_reports'] > 0 ? 'attention' : 'clear'],
			[$this->_('Pending requests'), (int)$stats['pending_requests'], 'inbox', $this->_('Awaiting member response'), '', 'neutral'],
			[$this->_('Active conversations'), (int)$stats['active_conversations'], 'comments', $this->_('Available conversations'), '', 'neutral'],
			[$this->_('Messages · 24h'), (int)$stats['messages_24h'], 'paper-plane', $this->_('Recent message activity'), '', 'neutral'],
			[$this->_('Restrictions'), (int)$stats['active_restrictions'], 'ban', $this->_('Members currently limited'), $baseUrl . 'restrictions/', (int)$stats['active_restrictions'] > 0 ? 'attention' : 'clear'],
		];
		$out .= '<section class="MessengerMetrics" aria-label="' . $this->_('Messenger metrics') . '">';
		foreach($metrics as [$label, $value, $icon, $description, $url, $state]) {
			$tag = $url !== '' ? 'a' : 'article';
			$out .= '<' . $tag . ' class="MessengerMetric" data-state="' . $state . '"' . ($url !== '' ? ' href="' . $this->e($url) . '"' : '') . '><span class="MessengerMetricIcon"><i class="fa fa-' . $icon . '" aria-hidden="true"></i></span><span class="MessengerMetricCopy"><span>' . $label . '</span><small>' . $description . '</small></span><strong>' . $value . '</strong>' . ($url !== '' ? '<i class="fa fa-chevron-right MessengerMetricArrow" aria-hidden="true"></i>' : '') . '</' . $tag . '>';
		}
		$out .= '</section>';

		$out .= '<div class="MessengerDashboardGrid"><section class="MessengerPanel MessengerDashboardQueue"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Moderation queue') . '</p><h2>' . $this->_('Reports needing attention') . '</h2><p>' . ((int)$stats['open_reports'] > 0 ? sprintf((int)$stats['open_reports'] === 1 ? $this->_('%d open report requires a decision.') : $this->_('%d open reports require a decision.'), (int)$stats['open_reports']) : $this->_('No unresolved member reports are waiting.')) . '</p></div><a class="uk-button uk-button-default" href="' . $this->e($baseUrl . 'reports/') . '">' . $this->_('View reports') . '</a></header>' . $this->reportTable($reports) . '</section><aside class="MessengerDashboardSidebar">';

		$out .= '<section class="MessengerPanel MessengerQuickActions"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Shortcuts') . '</p><h2>' . $this->_('Quick actions') . '</h2></div></header><nav aria-label="' . $this->_('Messenger quick actions') . '"><a href="' . $this->e($baseUrl . 'reports/') . '"><span class="MessengerQuickActionIcon"><i class="fa fa-flag" aria-hidden="true"></i></span><span><strong>' . $this->_('Review reports') . '</strong><small>' . $this->_('Triage and resolve member reports') . '</small></span><i class="fa fa-chevron-right" aria-hidden="true"></i></a><a href="' . $this->e($baseUrl . 'restrictions/') . '"><span class="MessengerQuickActionIcon"><i class="fa fa-ban" aria-hidden="true"></i></span><span><strong>' . $this->_('Manage restrictions') . '</strong><small>' . $this->_('Find a member or review active controls') . '</small></span><i class="fa fa-chevron-right" aria-hidden="true"></i></a>';
		if($m->canAdmin($this->wire('user'))) $out .= '<a href="' . $this->e($baseUrl . 'broadcasts/') . '"><span class="MessengerQuickActionIcon"><i class="fa fa-bullhorn" aria-hidden="true"></i></span><span><strong>' . $this->_('Send a broadcast') . '</strong><small>' . $this->_('Deliver one private message to every selected member') . '</small></span><i class="fa fa-chevron-right" aria-hidden="true"></i></a><a href="' . $this->e($baseUrl . 'settings/') . '"><span class="MessengerQuickActionIcon"><i class="fa fa-cog" aria-hidden="true"></i></span><span><strong>' . $this->_('Messenger settings') . '</strong><small>' . $this->_('Policies, notifications, and retention') . '</small></span><i class="fa fa-chevron-right" aria-hidden="true"></i></a>';
		$out .= '</nav></section>';

		$readiness = [
			['lock', $this->_('Encrypted storage'), $encryptionHealthy ? $this->_('Healthy') : ($plaintext > 0 ? sprintf($this->_('%d plaintext values'), $plaintext) : $this->_('Unavailable')), $encryptionHealthy ? 'healthy' : 'attention'],
			['envelope', $this->_('Email notifications'), (bool)$m->email_notifications ? $m->mailProviderLabel() : $this->_('Disabled'), (bool)$m->email_notifications ? 'healthy' : 'neutral'],
			['terminal', $this->_('Maintenance CLI'), (bool)$m->enable_cli ? $this->_('Enabled') : $this->_('Disabled'), (bool)$m->enable_cli ? 'healthy' : 'neutral'],
			['history', $this->_('Retention policy'), (int)$m->retention_days > 0 ? sprintf($this->_('%d days'), (int)$m->retention_days) : $this->_('No automatic deletion'), 'neutral'],
		];
		$out .= '<section class="MessengerPanel MessengerReadiness"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('System health') . '</p><h2>' . $this->_('Operational readiness') . '</h2></div></header><ul>';
		foreach($readiness as [$icon, $label, $value, $state]) $out .= '<li><span class="MessengerReadinessIcon"><i class="fa fa-' . $icon . '" aria-hidden="true"></i></span><span><strong>' . $label . '</strong><small>' . $this->e($value) . '</small></span><span class="MessengerReadinessDot" data-state="' . $state . '"><span class="uk-hidden">' . $this->e($state) . '</span></span></li>';
		$out .= '</ul></section></aside></div>';
		return $this->wrap($out);
	}

	public function ___executeReports(): string {
		$m=$this->messenger();$status=$this->wire('sanitizer')->name((string)$this->wire('input')->get('status'))?:'open';$labels=['open'=>'Open','reviewing'=>'Reviewing','resolved'=>'Resolved','dismissed'=>'Dismissed','all'=>'All'];if(!isset($labels[$status]))$status='open';$reports=$m->reports($this->wire('user'),$status,100);$counts=$m->reportStatusCounts($this->wire('user'));$this->headline($this->_('Messenger reports'));
		$out=$this->nav('reports') . '<header class="MessengerAdminHead"><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Moderation') . '</p><h2>' . $this->_('Reports') . '</h2><p>' . $this->_('Oldest unresolved reports appear first. Message content requires a separate permission and every decision is audited.') . '</p></div></header>';
		$out.='<section class="MessengerReportSummary" aria-label="' . $this->_('Report queue summary') . '"><a href="?status=open"><span>' . $this->_('Open') . '</span><strong>' . $counts['open'] . '</strong><small>' . $this->_('Waiting for review') . '</small></a><a href="?status=reviewing"><span>' . $this->_('Reviewing') . '</span><strong>' . $counts['reviewing'] . '</strong><small>' . $this->_('Assigned for a decision') . '</small></a><a href="?status=resolved"><span>' . $this->_('Resolved') . '</span><strong>' . $counts['resolved'] . '</strong><small>' . $this->_('Action completed') . '</small></a><a href="?status=all"><span>' . $this->_('All reports') . '</span><strong>' . $counts['all'] . '</strong><small>' . $this->_('Complete moderation history') . '</small></a></section>';
		$out.='<nav class="MessengerReportFilters" aria-label="' . $this->_('Report status') . '"><ul class="uk-subnav uk-subnav-pill">';foreach($labels as $key=>$label)$out.='<li' . ($status===$key?' class="uk-active"':'') . '><a href="?status=' . $key . '"' . ($status===$key?' aria-current="page"':'') . '><span>' . $this->_($label) . '</span><strong class="MessengerFilterCount">' . $counts[$key] . '</strong></a></li>'; $out.='</ul></nav><section class="MessengerPanel MessengerReportsPanel"><header class="MessengerReportsToolbar"><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Current view') . '</p><h2>' . $this->_($labels[$status]) . '</h2></div><p>' . sprintf($counts[$status]===1?$this->_('%d report'):$this->_('%d reports'),$counts[$status]) . '</p></header>' . $this->reportTable($reports,$status) . '</section>';
		return $this->wrap($out);
	}

	public function ___executeReport(): string {
		$m=$this->messenger();$id=(int)$this->wire('input')->get('id');
		if($this->wire('input')->requestMethod('POST')){
			try{$this->wire('session')->CSRF->validate();$m->updateReport($id,$this->wire('user'),$this->wire('sanitizer')->name((string)$this->wire('input')->post('status')),(string)$this->wire('input')->post('resolution'));$this->message($this->_('Report updated.'));}catch(\Throwable $e){$this->error($this->_('The report could not be updated.'));}
			$this->wire('session')->redirect($this->wire('page')->url . 'report/?id=' . $id);
		}
		$report=$m->report($id,$this->wire('user'));if(!$report)throw new Wire404Exception('Report not found.');$this->headline(sprintf($this->_('Report #%d'),$id));
		$reporter=$this->wire('users')->get((int)$report['reporter_user_id']);$reported=$this->wire('users')->get((int)$report['reported_user_id']);
		$out=$this->nav('reports') . '<p><a href="' . $this->e($this->wire('page')->url . 'reports/') . '">← ' . $this->_('Back to reports') . '</a></p><div class="MessengerReportLayout"><main><section class="MessengerPanel"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->e($report['category']) . '</p><h2>' . sprintf($this->_('Report #%d'),$id) . '</h2></div><span class="uk-label">' . $this->e($report['status']) . '</span></header>';
		if(isset($report['evidence_body']))$out.='<div class="MessengerEvidence"><strong>' . $this->_('Preserved evidence') . '</strong><p>' . nl2br($this->e($report['evidence_body'])) . '</p><small>' . $this->_('Evidence fingerprint') . ': <code>' . $this->e($report['evidence_hash']) . '</code></small></div>';
		else $out.='<div class="uk-alert-warning" uk-alert><p>' . $this->_('Message content is hidden. The messenger-view-content permission is required.') . '</p></div>';
		if(isset($report['comment'])&&trim((string)$report['comment'])!=='')$out.='<h3>' . $this->_('Reporter comment') . '</h3><p>' . nl2br($this->e($report['comment'])) . '</p>';
		$out.='</section><form class="MessengerPanel" method="post">' . $this->csrf() . '<h2>' . $this->_('Decision') . '</h2><label class="uk-form-label" for="report-status">' . $this->_('Status') . '</label><select class="uk-select" id="report-status" name="status">';foreach(['open','reviewing','resolved','dismissed'] as $state)$out.='<option value="' . $state . '"' . ($report['status']===$state?' selected':'') . '>' . ucfirst($state) . '</option>';$out.='</select><label class="uk-form-label" for="report-resolution">' . $this->_('Reason and resolution') . '</label><textarea class="uk-textarea" id="report-resolution" name="resolution" rows="6">' . $this->e($report['resolution']) . '</textarea><button class="uk-button uk-button-primary" type="submit">' . $this->_('Save decision') . '</button></form></main><aside><section class="MessengerPanel"><h2>' . $this->_('People') . '</h2><dl class="uk-description-list uk-description-list-divider"><dt>' . $this->_('Reported by') . '</dt><dd>' . $this->e($reporter->id?($reporter->get('title')?:$reporter->name):'Unavailable') . ' · #' . (int)$report['reporter_user_id'] . '</dd><dt>' . $this->_('Reported member') . '</dt><dd>' . $this->e($reported->id?($reported->get('title')?:$reported->name):'Unavailable') . ' · #' . (int)$report['reported_user_id'] . '</dd><dt>' . $this->_('Message') . '</dt><dd>#' . (int)$report['message_id'] . '</dd><dt>' . $this->_('Created') . '</dt><dd>' . $this->e($report['created_at']) . '</dd></dl><a class="uk-button uk-button-danger uk-width-1-1" href="' . $this->e($this->wire('page')->url . 'restrictions/?user_id=' . (int)$report['reported_user_id']) . '">' . $this->_('Restrict member') . '</a></section></aside></div>';
		return $this->wrap($out);
	}

	public function ___executeRestrictions(): string {
		$m=$this->messenger();$input=$this->wire('input');$users=$this->wire('users');$targetId=(int)($input->post('user_id')?:$input->get('user_id'));$query=trim((string)$input->get('q'));
		if($this->wire('input')->requestMethod('POST')){
			try{$this->wire('session')->CSRF->validate();$target=$this->wire('users')->get($targetId);$action=(string)$this->wire('input')->post('restriction_action');if($action==='clear')$m->clearRestriction($target,$this->wire('user'));else{$days=max(1,min(365,(int)$this->wire('input')->post('days')));$m->restrictUser($target,$this->wire('user'),date('Y-m-d H:i:s',time()+$days*86400),(string)$this->wire('input')->post('reason'));}$this->message($this->_('Restriction updated.'));}catch(\Throwable $e){$this->error($this->_('The restriction could not be updated.'));}
			$this->wire('session')->redirect($this->wire('page')->url . 'restrictions/?user_id=' . $targetId);
		}
		$matches=[];if($query!==''){if(ctype_digit($query)){$candidate=$users->get((int)$query);if($candidate->id&&!$candidate->isGuest()&&!$candidate->isSuperuser()){$matches[]=$candidate;$targetId=(int)$candidate->id;}}else{$value=$this->wire('sanitizer')->selectorValue($query);foreach($users->find('include=all,limit=12,sort=name,name|email*=' . $value) as $candidate)if(!$candidate->isGuest()&&!$candidate->isSuperuser())$matches[]=$candidate;}}
		$active=$m->activeRestrictions($this->wire('user'),100);$stats=$m->moderationStats($this->wire('user'));$this->headline($this->_('Member restrictions'));
		$out=$this->nav('restrictions') . '<header class="MessengerAdminHead"><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Safety controls') . '</p><h2>' . $this->_('Member restrictions') . '</h2><p>' . $this->_('Temporarily stop a member from sending or receiving messages. Every change is permission-gated and audited.') . '</p></div><span class="MessengerRestrictionTotal"><strong>' . (int)$stats['active_restrictions'] . '</strong><span>' . $this->_('Active') . '</span></span></header>';
		$out.='<section class="MessengerPanel MessengerRestrictionSearch"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Find a member') . '</p><h2>' . $this->_('Search members') . '</h2></div></header><form method="get" role="search"><label class="uk-form-label" for="restriction-query">' . $this->_('Username, email, or user ID') . '</label><div class="MessengerSearchControl"><span class="fa fa-search" aria-hidden="true"></span><input class="uk-input" id="restriction-query" name="q" type="search" value="' . $this->e($query) . '" placeholder="' . $this->_('Search members') . '" autocomplete="off" required><button class="uk-button uk-button-primary" type="submit">' . $this->_('Search') . '</button></div><p class="uk-text-meta">' . $this->_('Search is limited to eligible non-superuser accounts.') . '</p></form></section>';
		if($query!==''){$out.='<section class="MessengerSearchResults" aria-label="' . $this->_('Member search results') . '"><header><h2>' . $this->_('Search results') . '</h2><span>' . sprintf(count($matches)===1?$this->_('%d member'):$this->_('%d members'),count($matches)) . '</span></header>';if(!$matches)$out.='<div class="MessengerEmpty"><i class="fa fa-search" aria-hidden="true"></i><h3>' . $this->_('No eligible members found') . '</h3><p>' . $this->_('Check the username, email, or numeric user ID and try again.') . '</p></div>';else{$out.='<div class="MessengerMemberResults">';foreach($matches as $candidate){$name=(string)($candidate->get('title')?:$candidate->name);$initial=mb_strtoupper(mb_substr($name,0,1));$out.='<a class="MessengerMemberCard" href="?user_id=' . (int)$candidate->id . '"><span class="MessengerMemberAvatar">' . $this->e($initial) . '</span><span><strong>' . $this->e($name) . '</strong><small>@' . $this->e($candidate->name) . ' · #' . (int)$candidate->id . '</small></span><i class="fa fa-chevron-right" aria-hidden="true"></i></a>';}$out.='</div>';}$out.='</section>';}
		if($targetId){$target=$users->get($targetId);if($target->id&&!$target->isGuest()&&!$target->isSuperuser()){$state=$m->restrictionStatus($target,$this->wire('user'));$name=(string)($target->get('title')?:$target->name);$initial=mb_strtoupper(mb_substr($name,0,1));$out.='<section class="MessengerRestrictionWorkspace"><form class="MessengerPanel MessengerRestrictionForm" method="post">' . $this->csrf() . '<input type="hidden" name="user_id" value="' . $targetId . '"><header class="MessengerSelectedMember"><span class="MessengerMemberAvatar">' . $this->e($initial) . '</span><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Selected member') . '</p><h2>' . $this->e($name) . '</h2><small>@' . $this->e($target->name) . ' · #' . $targetId . '</small></div><span class="MessengerRestrictionState" data-state="' . ($state['active']?'active':'clear') . '">' . ($state['active']?$this->_('Restricted'):$this->_('Not restricted')) . '</span></header><div class="MessengerRestrictionFields"><label><span class="uk-form-label">' . $this->_('Duration') . '</span><select class="uk-select" id="restriction-days" name="days"><option value="1">' . $this->_('1 day') . '</option><option value="7" selected>' . $this->_('7 days') . '</option><option value="14">' . $this->_('14 days') . '</option><option value="30">' . $this->_('30 days') . '</option><option value="90">' . $this->_('90 days') . '</option><option value="365">' . $this->_('1 year') . '</option></select></label><label><span class="uk-form-label">' . $this->_('Reason') . '</span><textarea class="uk-textarea" id="restriction-reason" name="reason" rows="4" placeholder="' . $this->_('Explain the moderation reason for the audit trail') . '" required></textarea></label></div><div class="MessengerRestrictionNotice"><i class="fa fa-info-circle" aria-hidden="true"></i><p>' . $this->_('The member will be unable to use Messenger until the restriction expires or is cleared. Existing conversations and evidence are retained.') . '</p></div><div class="MessengerRestrictionActions"><button class="uk-button uk-button-danger" name="restriction_action" value="restrict" type="submit">' . ($state['active']?$this->_('Update restriction'):$this->_('Restrict messaging')) . '</button>' . ($state['active']?'<button class="uk-button uk-button-default" name="restriction_action" value="clear" type="submit" formnovalidate>' . $this->_('Clear restriction') . '</button>':'') . '</div></form><aside class="MessengerPanel MessengerRestrictionContext"><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Current state') . '</p><h2>' . ($state['active']?$this->_('Restriction active'):$this->_('Messaging available')) . '</h2>' . ($state['active']?'<dl><dt>' . $this->_('Expires') . '</dt><dd>' . $this->e($this->formatAdminDate((string)$state['expires_at'])) . '</dd><dt>' . $this->_('Reason') . '</dt><dd>' . $this->e((string)$state['reason']) . '</dd></dl>':'<p>' . $this->_('This member can currently send and receive messages, subject to normal Messenger policy.') . '</p>') . '</aside></section>';}else $out.='<div class="uk-alert-warning" uk-alert><p>' . $this->_('This account cannot be restricted.') . '</p></div>';}
		$out.='<section class="MessengerPanel MessengerActiveRestrictions"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Active controls') . '</p><h2>' . $this->_('Active restrictions') . '</h2></div><span>' . sprintf((int)$stats['active_restrictions']===1?$this->_('%d member'):$this->_('%d members'),(int)$stats['active_restrictions']) . '</span></header>' . $this->restrictionTable($active) . '</section>';
		return $this->wrap($out);
	}

	public function ___executeBroadcasts(): string {
		$m=$this->messenger();$actor=$this->wire('user');if(!$m->canAdmin($actor))throw new WirePermissionException('Messenger administration denied.');
		$input=$this->wire('input');$session=$this->wire('session');$audience=(string)($input->post('audience')?:'all');$role=(string)$input->post('role');$body=(string)$input->post('body');$preview=null;
		if(!$input->requestMethod('POST'))$session->removeFor('ProcessMessenger','broadcastPreview');
		if($input->requestMethod('POST')){
			try{
				$this->wire('session')->CSRF->validate();$action=(string)$input->post('broadcast_action');
				if($action==='preview'){$preview=$m->previewBroadcast($actor,$audience,$role);$session->setFor('ProcessMessenger','broadcastPreview',['audience'=>$preview['audience'],'role'=>$preview['audience_value'],'body_hash'=>hash('sha256',$body),'recipient_count'=>(int)$preview['recipient_count']]);}
				elseif($action==='create'){
					$review=$session->getFor('ProcessMessenger','broadcastPreview');$current=$m->previewBroadcast($actor,$audience,$role);
					if(!is_array($review)||($review['audience']??'')!==$current['audience']||($review['role']??'')!==$current['audience_value']||!hash_equals((string)($review['body_hash']??''),hash('sha256',$body))||(int)($review['recipient_count']??-1)!==(int)$current['recipient_count'])throw new WireException('The audience or message changed. Preview the recipients again before sending.');
					if(!(bool)$input->post('confirm_broadcast'))throw new WireException('Confirm the reviewed recipient count before sending.');
					$created=$m->createBroadcast($actor,$body,$audience,$role);$m->processBroadcast((int)$created['id'],$actor,100,true);
					$session->removeFor('ProcessMessenger','broadcastPreview');
					$this->wire('session')->redirect($this->wire('page')->url . 'broadcast/?id=' . (int)$created['id']);
				}
			}catch(\Throwable $error){$this->error($error->getMessage());}
		}
		$roles=[];foreach($this->wire('roles')->find('sort=name') as $candidate)if($candidate->name!=='guest')$roles[(string)$candidate->name]=(string)($candidate->title?:$candidate->name);
		$recent=$m->broadcasts($actor,50);$this->headline($this->_('Messenger broadcasts'));
		$out=$this->nav('broadcasts') . '<header class="MessengerAdminHead"><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Member communication') . '</p><h2>' . $this->_('Send a message to members') . '</h2><p>' . $this->_('Create one private conversation message for every eligible member in the audience you review.') . '</p></div></header>';
		$out.='<ol class="MessengerBroadcastSteps" aria-label="' . $this->_('Broadcast workflow') . '"><li data-state="' . ($preview?'complete':'active') . '"><span>1</span><div><strong>' . $this->_('Choose audience') . '</strong><small>' . $this->_('All members or one role') . '</small></div></li><li data-state="' . ($preview?'complete':'next') . '"><span>2</span><div><strong>' . $this->_('Write message') . '</strong><small>' . $this->_('This becomes the private message') . '</small></div></li><li data-state="' . ($preview?'active':'next') . '"><span>3</span><div><strong>' . $this->_('Review and send') . '</strong><small>' . $this->_('See the exact recipient count first') . '</small></div></li></ol>';
		$out.='<div class="MessengerBroadcastLayout"><form class="MessengerPanel MessengerBroadcastComposer" method="post" data-broadcast-form data-preview-ready="' . ($preview?'true':'false') . '">' . $this->csrf() . '<header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('New broadcast') . '</p><h2>' . $this->_('Message details') . '</h2></div><span class="MessengerBroadcastSafety"><i class="fa fa-lock" aria-hidden="true"></i>' . $this->_('Encrypted at rest') . '</span></header>';
		$out.='<section class="MessengerBroadcastFormStep"><span class="MessengerBroadcastStepNumber">1</span><div><h3>' . $this->_('Who should receive it?') . '</h3><p>' . $this->_('The sender account is always excluded. Unavailable and restricted accounts are skipped.') . '</p><div class="MessengerBroadcastAudience"><label><span class="uk-form-label">' . $this->_('Audience') . '</span><select class="uk-select" name="audience" data-broadcast-audience><option value="all"' . ($audience==='all'?' selected':'') . '>' . $this->_('All eligible members') . '</option><option value="role"' . ($audience==='role'?' selected':'') . '>' . $this->_('Only members with a selected role') . '</option></select><small>' . $this->_('Choose a role to limit this message to one group.') . '</small></label><label data-broadcast-role><span class="uk-form-label">' . $this->_('Member role') . '</span><select class="uk-select" name="role"><option value="">' . $this->_('Select a role') . '</option>';foreach($roles as $name=>$label)$out.='<option value="' . $this->e($name) . '"' . ($role===$name?' selected':'') . '>' . $this->e($label) . '</option>';$out.='</select><small>' . $this->_('Only published, eligible members with this role are counted.') . '</small></label></div></div></section>';
		$out.='<section class="MessengerBroadcastFormStep"><span class="MessengerBroadcastStepNumber">2</span><div><h3>' . $this->_('What will members receive?') . '</h3><p>' . sprintf($this->_('The message is sent from %s and appears in each recipient’s Messenger inbox.'),$this->e((string)($actor->get('title')?:$actor->name))) . '</p><label><span class="uk-form-label">' . $this->_('Private message') . '</span><textarea class="uk-textarea" name="body" rows="8" maxlength="' . max(1,(int)$m->max_message_length) . '" placeholder="' . $this->_('Write the message exactly as members should see it…') . '" data-broadcast-body required>' . $this->e($body) . '</textarea><small class="MessengerBroadcastCharacterCount" data-broadcast-count>' . sprintf($this->_('0 of %d characters'),max(1,(int)$m->max_message_length)) . '</small></label></div></section>';
		$out.='<section class="MessengerBroadcastFormStep MessengerBroadcastReview"><span class="MessengerBroadcastStepNumber">3</span><div><h3>' . $this->_('Review recipients before sending') . '</h3>';
		if($preview){$recipientCount=(int)$preview['recipient_count'];$out.='<div class="MessengerBroadcastPreview" data-broadcast-preview><span><i class="fa fa-users" aria-hidden="true"></i></span><div><strong>' . sprintf($recipientCount===1?$this->_('%d eligible recipient'):$this->_('%d eligible recipients'),$recipientCount) . '</strong><small>' . $this->e((string)$preview['label']) . '</small></div><span class="MessengerBroadcastReviewed"><i class="fa fa-check" aria-hidden="true"></i> ' . $this->_('Reviewed') . '</span></div><p class="MessengerBroadcastStale" data-broadcast-stale hidden><i class="fa fa-refresh" aria-hidden="true"></i> ' . $this->_('The audience or message changed. Check recipients again before sending.') . '</p>';if($recipientCount>0)$out.='<label class="MessengerBroadcastConfirm"><input class="uk-checkbox" type="checkbox" name="confirm_broadcast" value="1" required><span>' . sprintf($recipientCount===1?$this->_('I confirm sending this private message to %d recipient.'):$this->_('I confirm sending this private message to %d recipients.'),$recipientCount) . '</span></label>';else $out.='<p class="MessengerBroadcastNoRecipients"><i class="fa fa-info-circle" aria-hidden="true"></i> ' . $this->_('No message can be sent until this audience contains at least one eligible member.') . '</p>';$out.='<div class="MessengerBroadcastActions"><button class="uk-button uk-button-default" name="broadcast_action" value="preview" type="submit" formnovalidate><i class="fa fa-refresh" aria-hidden="true"></i> ' . $this->_('Check again') . '</button>';if($recipientCount>0)$out.='<button class="uk-button uk-button-primary" name="broadcast_action" value="create" type="submit" data-broadcast-send><i class="fa fa-paper-plane" aria-hidden="true"></i> ' . sprintf($recipientCount===1?$this->_('Send to %d recipient'):$this->_('Send to %d recipients'),$recipientCount) . '</button>';$out.='</div>';}else{$out.='<div class="MessengerBroadcastReviewIntro"><i class="fa fa-eye" aria-hidden="true"></i><div><strong>' . $this->_('Check before anything is sent') . '</strong><p>' . $this->_('We will count the current eligible recipients and return you here for final confirmation. Previewing does not send a message.') . '</p></div></div><div class="MessengerBroadcastActions"><button class="uk-button uk-button-primary" name="broadcast_action" value="preview" type="submit"><i class="fa fa-users" aria-hidden="true"></i> ' . $this->_('Check recipients') . '</button></div>';}$out.='</div></section><p class="MessengerBroadcastQueueNote"><i class="fa fa-info-circle" aria-hidden="true"></i> ' . $this->_('After confirmation, up to 100 recipients are delivered immediately. Larger audiences continue safely in batches, and progress appears in Delivery history.') . '</p></form>';
		$out.='<aside class="MessengerPanel MessengerBroadcastGuidance"><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('What happens next') . '</p><h2>' . $this->_('After you press Send') . '</h2><ol><li><span>1</span><p><strong>' . $this->_('Recipients are locked in') . '</strong><small>' . $this->_('The reviewed audience is saved so later role changes do not alter this broadcast.') . '</small></p></li><li><span>2</span><p><strong>' . $this->_('Private messages are created') . '</strong><small>' . $this->_('Each member gets one normal, encrypted conversation message from your account.') . '</small></p></li><li><span>3</span><p><strong>' . $this->_('Delivery is tracked') . '</strong><small>' . $this->_('You can see delivered, skipped, failed, and pending totals in the history below.') . '</small></p></li></ol><div class="MessengerBroadcastWarning"><i class="fa fa-exclamation-triangle" aria-hidden="true"></i><p><strong>' . $this->_('This action contacts real members') . '</strong><small>' . $this->_('Use Check recipients whenever you change the audience or message. Duplicate delivery is prevented during retries.') . '</small></p></div></aside></div>';
		$out.='<section class="MessengerPanel MessengerBroadcastHistory"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Delivery history') . '</p><h2>' . $this->_('Recent member messages') . '</h2><p>' . $this->_('Open a broadcast to inspect its message, audience, and delivery totals.') . '</p></div><span>' . sprintf(count($recent)===1?$this->_('%d broadcast'):$this->_('%d broadcasts'),count($recent)) . '</span></header>' . $this->broadcastTable($recent) . '</section>';
		return $this->wrap($out);
	}

	public function ___executeBroadcast(): string {
		$m=$this->messenger();$actor=$this->wire('user');if(!$m->canAdmin($actor))throw new WirePermissionException('Messenger administration denied.');$id=(int)$this->wire('input')->get('id');
		if($this->wire('input')->requestMethod('POST')){
			try{$this->wire('session')->CSRF->validate();$action=(string)$this->wire('input')->post('broadcast_action');if($action==='cancel'){$m->cancelBroadcast($id,$actor);$this->message($this->_('Broadcast cancelled.'));}elseif($action==='process'){$result=$m->processBroadcast($id,$actor,100,true);$this->message(sprintf($this->_('%d recipients processed in this batch.'),(int)$result['batch_processed']));}}catch(\Throwable $error){$this->error($error->getMessage());}
			$this->wire('session')->redirect($this->wire('page')->url . 'broadcast/?id=' . $id);
		}
		$broadcast=$m->broadcast($id,$actor);if(!$broadcast)throw new Wire404Exception('Broadcast not found.');$sender=$this->wire('users')->get((int)$broadcast['sender_user_id']);$pending=max(0,(int)$broadcast['total_count']-(int)$broadcast['processed_count']);$percent=(int)$broadcast['total_count']>0?(int)round(((int)$broadcast['processed_count']/(int)$broadcast['total_count'])*100):100;$this->headline(sprintf($this->_('Broadcast #%d'),$id));
		$out=$this->nav('broadcasts') . '<p><a href="' . $this->e($this->wire('page')->url . 'broadcasts/') . '">← ' . $this->_('Back to broadcasts') . '</a></p><header class="MessengerAdminHead MessengerBroadcastDetailHead"><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Broadcast delivery') . '</p><h2>' . sprintf($this->_('Broadcast #%d'),$id) . '</h2><p>' . $this->_('Review delivery progress and process the next safe batch when needed.') . '</p></div><span class="MessengerStatusBadge" data-state="' . $this->e((string)$broadcast['status']) . '">' . $this->e(ucfirst((string)$broadcast['status'])) . '</span></header>';
		$out.='<section class="MessengerBroadcastProgress"><div><span>' . $this->_('Progress') . '</span><strong>' . $percent . '%</strong></div><progress max="100" value="' . $percent . '">' . $percent . '%</progress><dl><div><dt>' . $this->_('Recipients') . '</dt><dd>' . (int)$broadcast['total_count'] . '</dd></div><div><dt>' . $this->_('Delivered') . '</dt><dd>' . (int)$broadcast['delivered_count'] . '</dd></div><div><dt>' . $this->_('Skipped') . '</dt><dd>' . (int)$broadcast['skipped_count'] . '</dd></div><div><dt>' . $this->_('Failed') . '</dt><dd>' . (int)$broadcast['failed_count'] . '</dd></div><div><dt>' . $this->_('Pending') . '</dt><dd>' . $pending . '</dd></div></dl></section>';
		$out.='<div class="MessengerBroadcastDetailGrid"><section class="MessengerPanel"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">' . $this->_('Message') . '</p><h2>' . $this->_('Delivered content') . '</h2></div></header><div class="MessengerBroadcastBody">' . nl2br($this->e((string)$broadcast['body'])) . '</div></section><aside class="MessengerPanel MessengerBroadcastMeta"><h2>' . $this->_('Details') . '</h2><dl><dt>' . $this->_('Audience') . '</dt><dd>' . $this->e($broadcast['audience']==='role'?'Role: ' . $broadcast['audience_value']:'All eligible members') . '</dd><dt>' . $this->_('Sender') . '</dt><dd>' . $this->e($sender->id?($sender->get('title')?:$sender->name):'Unavailable') . '</dd><dt>' . $this->_('Created') . '</dt><dd>' . $this->e($this->formatAdminDate((string)$broadcast['created_at'])) . '</dd><dt>' . $this->_('Completed') . '</dt><dd>' . $this->e($broadcast['completed_at']?$this->formatAdminDate((string)$broadcast['completed_at']):'—') . '</dd></dl>';
		if(in_array((string)$broadcast['status'],['queued','running'],true))$out.='<form method="post">' . $this->csrf() . '<div class="MessengerBroadcastDetailActions"><button class="uk-button uk-button-primary" name="broadcast_action" value="process" type="submit">' . $this->_('Deliver next 100') . '</button><button class="uk-button uk-button-danger" name="broadcast_action" value="cancel" type="submit">' . $this->_('Cancel pending') . '</button></div></form>';$out.='</aside></div>';
		return $this->wrap($out);
	}

	public function ___executeSettings(): string { if(!$this->messenger()->canAdmin($this->wire('user')))throw new WirePermissionException('Messenger administration denied.');$this->wire('session')->redirect($this->wire('config')->urls->admin . 'module/edit?name=Messenger');return ''; }

	private function broadcastTable(array $broadcasts): string {
		if(!$broadcasts)return '<div class="MessengerEmpty MessengerBroadcastEmpty"><i class="fa fa-bullhorn" aria-hidden="true"></i><h3>' . $this->_('No broadcasts yet') . '</h3><p>' . $this->_('Create a carefully reviewed member message above.') . '</p></div>';
		$out='<div class="uk-overflow-auto"><table class="uk-table uk-table-divider uk-table-hover uk-table-middle MessengerBroadcastTable"><thead><tr><th>' . $this->_('Broadcast') . '</th><th>' . $this->_('Audience') . '</th><th>' . $this->_('Status') . '</th><th>' . $this->_('Delivery') . '</th><th>' . $this->_('Created') . '</th><th><span class="uk-hidden">' . $this->_('Actions') . '</span></th></tr></thead><tbody>';
		foreach($broadcasts as $broadcast){$url=$this->wire('page')->url . 'broadcast/?id=' . (int)$broadcast['id'];$audience=$broadcast['audience']==='role'?'Role: ' . $broadcast['audience_value']:$this->_('All eligible members');$out.='<tr><td><a href="' . $this->e($url) . '"><strong>' . sprintf($this->_('Broadcast #%d'),(int)$broadcast['id']) . '</strong></a></td><td>' . $this->e($audience) . '</td><td><span class="MessengerStatusBadge" data-state="' . $this->e((string)$broadcast['status']) . '">' . $this->e(ucfirst((string)$broadcast['status'])) . '</span></td><td><strong>' . (int)$broadcast['delivered_count'] . ' / ' . (int)$broadcast['total_count'] . '</strong><small class="MessengerMemberId">' . sprintf($this->_('%d failed'),(int)$broadcast['failed_count']) . '</small></td><td>' . $this->e($this->formatAdminDate((string)$broadcast['created_at'])) . '</td><td><a class="uk-button uk-button-small uk-button-default" href="' . $this->e($url) . '">' . $this->_('View') . '</a></td></tr>';}
		return $out . '</tbody></table></div>';
	}

	private function reportTable(array $reports,string $scope='open'): string {
		if(!$reports){$states=['open'=>['Inbox is clear','There are no open reports requiring moderation.'],'reviewing'=>['Nothing under review','Reports being actively reviewed will appear here.'],'resolved'=>['No resolved reports','Completed moderation decisions will appear here.'],'dismissed'=>['No dismissed reports','Dismissed reports will appear here.'],'all'=>['No reports yet','Member reports will appear here when they are submitted.']];[$title,$copy]=$states[$scope]??$states['open'];return '<div class="MessengerEmpty MessengerReportsEmpty"><span class="MessengerEmptyIcon"><i class="fa fa-shield" aria-hidden="true"></i><i class="fa fa-check" aria-hidden="true"></i></span><h3>' . $this->_($title) . '</h3><p>' . $this->_($copy) . '</p></div>';}
		$out='<div class="uk-overflow-auto"><table class="uk-table uk-table-divider uk-table-hover uk-table-middle MessengerReportTable"><thead><tr><th>' . $this->_('Report') . '</th><th>' . $this->_('Category') . '</th><th>' . $this->_('Reported member') . '</th><th>' . $this->_('Status') . '</th><th>' . $this->_('Created') . '</th><th><span class="uk-hidden">' . $this->_('Actions') . '</span></th></tr></thead><tbody>';
		foreach($reports as $report){$url=$this->wire('page')->url . 'report/?id=' . (int)$report['id'];$member=$this->wire('users')->get((int)$report['reported_user_id']);$memberName=$member->id?(string)($member->get('title')?:$member->name):$this->_('Unavailable member');$created=(string)$report['created_at'];$timestamp=strtotime($created);$out.='<tr><td><a class="MessengerReportLink" href="' . $this->e($url) . '"><strong>' . sprintf($this->_('Report #%d'),(int)$report['id']) . '</strong><small>' . sprintf($this->_('Message #%d'),(int)$report['message_id']) . '</small></a></td><td><span class="MessengerCategoryBadge">' . $this->e(ucfirst((string)$report['category'])) . '</span></td><td><strong>' . $this->e($memberName) . '</strong><small class="MessengerMemberId">#' . (int)$report['reported_user_id'] . '</small></td><td><span class="MessengerStatusBadge" data-state="' . $this->e($report['status']) . '">' . $this->e(ucfirst((string)$report['status'])) . '</span></td><td><time datetime="' . $this->e($created) . '">' . $this->e($timestamp?date('M j, Y · H:i',$timestamp):$created) . '</time></td><td><a class="uk-button uk-button-small uk-button-default" href="' . $this->e($url) . '">' . $this->_('Review') . '</a></td></tr>';}
		return $out . '</tbody></table></div>';
	}

	private function restrictionTable(array $restrictions): string {
		if(!$restrictions)return '<div class="MessengerEmpty MessengerRestrictionsEmpty"><span class="MessengerEmptyIcon"><i class="fa fa-shield" aria-hidden="true"></i><i class="fa fa-check" aria-hidden="true"></i></span><h3>' . $this->_('No active restrictions') . '</h3><p>' . $this->_('Members with a temporary messaging restriction will appear here.') . '</p></div>';
		$out='<div class="uk-overflow-auto"><table class="uk-table uk-table-divider uk-table-hover uk-table-middle MessengerRestrictionTable"><thead><tr><th>' . $this->_('Member') . '</th><th>' . $this->_('Reason') . '</th><th>' . $this->_('Expires') . '</th><th><span class="uk-hidden">' . $this->_('Actions') . '</span></th></tr></thead><tbody>';
		foreach($restrictions as $restriction){$member=$this->wire('users')->get((int)$restriction['user_id']);$name=$member->id?(string)($member->get('title')?:$member->name):$this->_('Unavailable member');$url=$this->wire('page')->url . 'restrictions/?user_id=' . (int)$restriction['user_id'];$out.='<tr><td><strong>' . $this->e($name) . '</strong><small class="MessengerMemberId">@' . $this->e($member->id?$member->name:'unknown') . ' · #' . (int)$restriction['user_id'] . '</small></td><td><span class="MessengerRestrictionReason">' . $this->e((string)$restriction['reason']) . '</span></td><td>' . $this->e($this->formatAdminDate((string)$restriction['expires_at'])) . '</td><td><a class="uk-button uk-button-small uk-button-default" href="' . $this->e($url) . '">' . $this->_('Manage') . '</a></td></tr>';}
		return $out . '</tbody></table></div>';
	}

	private function formatAdminDate(string $value): string { $timestamp=strtotime($value);return $timestamp?date('M j, Y · H:i',$timestamp):$this->_('No expiry'); }

	private function nav(string $active): string {
		$items=[];
		if($this->messenger()->canModerate($this->wire('user'))) $items=['dashboard'=>['','Dashboard'],'reports'=>['reports/','Reports'],'restrictions'=>['restrictions/','Restrictions']];
		if($this->messenger()->canAdmin($this->wire('user'))) $items['broadcasts']=['broadcasts/','Broadcasts'];
		$out='<div class="MessengerAdminNavigation uk-margin-medium-bottom uk-flex uk-flex-top"><div class="uk-width-expand"><ul class="uk-subnav uk-subnav-pill MessengerAdminNav" aria-label="' . $this->_('Messenger sections') . '">';
		foreach($items as $key=>[$path,$label])$out.='<li' . ($active===$key?' class="uk-active"':'') . '><a href="' . $this->e($this->wire('page')->url . $path) . '"' . ($active===$key?' aria-current="page"':'') . '>' . $this->_($label) . '</a></li>';
		$out .= '</ul></div>';
		if($this->messenger()->canAdmin($this->wire('user'))) {
			$settings=$this->wire('page')->url . 'settings/';
			$out .= '<div class="uk-width-auto"><a class="MessengerAdminSettings uk-link-muted uk-display-inline-flex uk-flex-middle" href="' . $this->e($settings) . '" title="' . $this->_('Messenger settings') . '" aria-label="' . $this->_('Messenger settings') . '">' . $this->settingsIcon() . '</a></div>';
		}
		return $out . '</div>';
	}
